/**
 * Progressively enhance console-block tabs to use the WAI-ARIA "Tabs with
 * Automatic Activation" pattern, replacing the CSS-only radio button "tabs"
 * generated by the djangodocs Sphinx extension.
 * https://www.w3.org/WAI/ARIA/apg/patterns/tabs/examples/tabs-automatic/
 *
 * This uses GitHub's tab-container-element, an unstyled custom element that
 * implements the tab pattern with accurate ARIA roles and tabindex management
 * for keyboard support. https://github.com/github/tab-container-element
 *
 * This also persists and syncs the active tab across all console blocks on the
 * page and with other pages (including open browser tabs) in the same origin.
 */

import "./lib/tab-container-element.min.js";

const STORAGE_KEY = "django.console-tabs.selected";

let selectedTabName = readSavedTabName();

/**
 * Convert all console blocks on the page to tab-container-element and sync
 * their active tabs.
 */
function enhanceConsoleTabs(selector = "div.console-block") {
    for (const consoleBlock of document.querySelectorAll(selector)) {
        convertConsoleBlock(consoleBlock);
    }
    if (selectedTabName) {
        syncTabs(selectedTabName);
    }
}

/**
 * Convert a single <div class="console-block"> to a tab-container, replacing
 * it in the DOM. (If the div's content is not in the expected format, leave it
 * unchanged.)
 *
 * Original HTML from the djangodocs Sphinx extension:
 *   <div class="console-block" id="console-block-0">
 *     <input class="c-tab-unix" id="c-tab-0-unix" type="radio"
 *         name="console-0" checked>
 *     <label for="c-tab-0-unix">Unix/macOS</label>
 *     <input class="c-tab-win" id="c-tab-0-win" type="radio"
 *         name="console-0">
 *     <label for="c-tab-0-win">Windows</label>
 *     <section class="c-content-unix" id="c-content-0-unix">
 *       <div class="highlight-console notranslate">...</div>
 *     </section>
 *     <section class="c-content-win" id="c-content-0-win">
 *       <div class="highlight-doscon notranslate">...</div>
 *     </section>
 *   </div>
 *
 * After enhancement:
 *   <tab-container class="console-block" id="console-block-0">
 *     <button type="button" id="c-tab-0-unix" data-tab-name="unix"
 *         role="tab" aria-selected="true" tabindex="0">Unix/macOS</button>
 *     <button type="button" id="c-tab-0-win" data-tab-name="win"
 *         role="tab" aria-selected="false" tabindex="-1">Windows</button>
 *     <section class="c-content-unix" id="c-content-0-unix"
 *         role="tabpanel" aria-labelledby="c-tab-0-unix" tabindex="0">
 *       <div class="highlight-console notranslate">...</div>
 *     </section>
 *     <section class="c-content-win" id="c-content-0-win"
 *         role="tabpanel" aria-labelledby="c-tab-0-win" tabindex="0">
 *       <div class="highlight-doscon notranslate">...</div>
 *     </section>
 *   </tab-container>
 */
function convertConsoleBlock(consoleBlock) {
    const items = collectConsoleBlockContent(consoleBlock);
    if (!items) {
        // If any console-block content is not in the expected form, leave the
        // entire block unchanged.
        return;
    }

    const tabContainer = document.createElement("tab-container");
    tabContainer.classList.add("console-block");
    tabContainer.id = consoleBlock.id;
    for (const { tabName, selected, radio, label, section } of items) {
        const tab = createTab(radio, label, tabName, selected);
        tabContainer.appendChild(tab);
        convertSectionToPanel(section, tab); // In-place conversion.
    }
    for (const { section } of items) {
        tabContainer.appendChild(section); // Re-parent to tabContainer.
    }

    consoleBlock.replaceWith(tabContainer);
}

// In the original HTML, <input type="radio" class="c-tab-TABNAME"> controls
// the tab panel <section class="c-content-TABNAME">.
const RADIO_CLASS_PREFIX = "c-tab-";
const SECTION_CLASS_PREFIX = "c-content-";

/**
 * Extract tabName, selected state, and the radio, label and section elements
 * for each tab in the original console-block HTML. Return an array of objects
 * or null if the HTML does not match the expected form.
 *
 * This handles any number of tabs, allowing future additions in the djangodocs
 * extension (e.g., for PowerShell syntax).
 */
function collectConsoleBlockContent(consoleBlock) {
    const items = [];
    for (const radio of consoleBlock.querySelectorAll("input[type=radio]")) {
        const tabName = Array.from(radio.classList)
            .find((className) => className.startsWith(RADIO_CLASS_PREFIX))
            ?.slice(RADIO_CLASS_PREFIX.length);
        if (!tabName || !radio.id) {
            console.warn("Unknown console-block radio", radio, consoleBlock);
            return null;
        }
        const selected = radio.checked;
        const label = consoleBlock.querySelector(
            `label[for="${CSS.escape(radio.id)}"]`,
        );
        const sectionClass = `${SECTION_CLASS_PREFIX}${tabName}`;
        const section = consoleBlock.querySelector(
            `section[class~="${CSS.escape(sectionClass)}"]`,
        );
        if (!label || !section) {
            console.warn("Unknown console-block layout", radio, consoleBlock);
            return null;
        }
        items.push({ tabName, selected, radio, label, section });
    }
    if (!items.length) {
        console.warn("No console-block tabs found", consoleBlock);
        return null;
    }
    // Ensure there is nothing else in the block.
    const known = new Set(
        items.flatMap(({ radio, label, section }) => [radio, label, section]),
    );
    if (Array.from(consoleBlock.children).some((child) => !known.has(child))) {
        console.warn("Unexpected console-block content", consoleBlock);
        return null;
    }
    return items;
}

function createTab(radio, label, tabName, selected) {
    const tab = document.createElement("button");
    tab.type = "button";
    tab.id = radio.id;
    tab.dataset.tabName = tabName;
    tab.setAttribute("role", "tab");
    // Before Django 6.2, tab labels used FontAwesome icons with a text
    // description in the title attribute.
    let labelText = label.textContent;
    if (/\p{Private_Use}/u.test(labelText) && label.title) {
        labelText = label.title;
    }
    tab.textContent = labelText.trim();

    if (selected) {
        tab.setAttribute("aria-selected", "true");
    } else {
        tab.tabIndex = -1;
    }

    return tab;
}

function convertSectionToPanel(section, tab) {
    section.setAttribute("role", "tabpanel");
    section.setAttribute("aria-labelledby", tab.id);
    if (tab.getAttribute("aria-selected") !== "true") {
        section.hidden = true;
    }
    // tab-container applies tabIndex=0 to all panels.
    return section;
}

/**
 * Return the index of the tab with the given name in the tab container, or -1
 * if the container does not have that tab name.
 */
function findTabIndex(tabContainer, tabName) {
    return Array.from(tabContainer.querySelectorAll('[role="tab"]')).findIndex(
        (tab) => tab.dataset.tabName === tabName,
    );
}

let inSyncTabs = false;

/**
 * Sync the active tab in all console blocks to tabName (excluding
 * changedTabContainer if provided). If a console block does not have a tab
 * with the given name, it will be left unchanged.
 */
function syncTabs(tabName, changedTabContainer = null) {
    if (inSyncTabs || !tabName) {
        return;
    }
    inSyncTabs = true;
    try {
        selectedTabName = tabName;
        for (const tabContainer of document.querySelectorAll(
            "tab-container.console-block",
        )) {
            if (tabContainer !== changedTabContainer) {
                const tabIndex = findTabIndex(tabContainer, tabName);
                if (tabIndex >= 0) {
                    tabContainer.selectTab(tabIndex, { focus: false });
                }
            }
        }
    } finally {
        inSyncTabs = false;
    }
}

function readSavedTabName() {
    try {
        return localStorage.getItem(STORAGE_KEY);
    } catch {
        return null;
    }
}

function saveTabName(tabName) {
    try {
        localStorage.setItem(STORAGE_KEY, tabName);
    } catch {
        // Ignore storage failures. The tabs still work for the current page.
    }
}

function restoreSavedTab() {
    const savedTabName = readSavedTabName();

    if (savedTabName && savedTabName !== selectedTabName) {
        syncTabs(savedTabName);
    }
}

async function init() {
    await customElements.whenDefined("tab-container");
    enhanceConsoleTabs();

    document.addEventListener("tab-container-changed", (event) => {
        if (inSyncTabs || !event.target.classList.contains("console-block")) {
            return;
        }

        const tabName = event.tab?.dataset.tabName;
        if (!tabName) {
            return;
        }

        syncTabs(tabName, event.target);
        saveTabName(tabName);
    });

    window.addEventListener("pageshow", (event) => {
        if (event.persisted) {
            restoreSavedTab();
        }
    });

    window.addEventListener("storage", (event) => {
        if (event.key === STORAGE_KEY && event.newValue) {
            syncTabs(event.newValue);
        }
    });
}

// (Script modules are deferred, so it's safe to init immediately here.)
void init();
